// Created: 2026-04-17

/**
 * Thrash Detector — UserPromptSubmit hook
 *
 * Source: usage analytics — recurring edit→format→revert→re-edit and
 * edit→test-fail→undo→re-edit loops that burn 10+ turns on the same
 * file. Catches the "same-file repeatedly" signal early and suggests a
 * different approach.
 *
 * Reads `.claude/state/edit-history.jsonl` (maintained by
 * posttool/write/edit-history-tracker) and computes per-file edit
 * counts in the rolling window. If any single file has been edited
 * THRASH_THRESHOLD times in WINDOW_ENTRIES most recent events, inject
 * an advisory additionalContext.
 *
 * Also truncates the history file to MAX_ENTRIES on read, keeping
 * the JSONL bounded without a separate sweeper.
 */

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { isAbsolute, join, relative } from 'node:path';
import type { HookInput, HookResult, HookContext } from '../types.js';
import { outputSilentSuccess, outputNotify } from '../lib/common.js';
import { getEditHistoryPath } from '../posttool/write/edit-history-tracker.js';
import { NOOP_CTX } from '../lib/context.js';

const HOOK_NAME = 'prompt/thrash-detector';

// If any single file appears >= THRASH_THRESHOLD times in the last
// WINDOW_ENTRIES edit events, flag as thrash.
const THRASH_THRESHOLD = 3;
const WINDOW_ENTRIES = 10;

// Hard cap on the JSONL size — trimmed on every invocation.
const MAX_ENTRIES = 50;

interface EditEntry {
  t: number;
  f: string;
  tool?: string;
  sid?: string;
  /** Editing subagent's agent_id; absent for the main thread (#4651). */
  agent?: string;
}

/** Newest warned edit time per session, so a repeat needs a newer edit (#4651). */
type WarnedState = Record<string, number>;

function getWarnedStatePath(projectDir: string): string {
  return join(projectDir, '.claude', 'state', 'thrash-warned.json');
}

function readWarnedState(path: string): WarnedState {
  if (!existsSync(path)) return {};
  try {
    const raw: unknown = JSON.parse(readFileSync(path, 'utf8'));
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return {};
    const out: WarnedState = {};
    for (const [k, v] of Object.entries(raw)) {
      if (typeof v === 'number' && Number.isFinite(v)) out[k] = v;
    }
    return out;
  } catch {
    return {};
  }
}

/** Path relative to the project when inside it, else the absolute path. */
function displayPath(file: string, projectDir: string): string {
  if (!projectDir) return file;
  const rel = relative(projectDir, file);
  if (!rel || rel.startsWith('..') || isAbsolute(rel)) return file;
  return rel;
}

/**
 * Read recent edit events (up to MAX_ENTRIES). Truncates the file
 * in-place if it exceeded the cap.
 */
function readAndTrimHistory(path: string): EditEntry[] {
  if (!existsSync(path)) return [];
  let content: string;
  try {
    content = readFileSync(path, 'utf8');
  } catch {
    return [];
  }
  const entries: EditEntry[] = [];
  for (const line of content.split('\n')) {
    if (!line.trim()) continue;
    try {
      const parsed = JSON.parse(line) as EditEntry;
      if (parsed.f && typeof parsed.t === 'number') entries.push(parsed);
    } catch {
      // skip malformed lines
    }
  }
  if (entries.length > MAX_ENTRIES) {
    const trimmed = entries.slice(-MAX_ENTRIES);
    try {
      writeFileSync(path, `${trimmed.map(e => JSON.stringify(e)).join('\n')}\n`, 'utf8');
    } catch {
      // best-effort
    }
    return trimmed;
  }
  return entries;
}

/**
 * Analyze the last WINDOW_ENTRIES events and return files that hit the
 * thrash threshold. Counts are per (file, agent): subagents share the
 * parent's session id, and one edit each by three agents is not a loop
 * (#4651). The returned map is keyed by file with the highest per-agent
 * count.
 */
function findThrashingFiles(entries: EditEntry[]): Map<string, number> {
  const window = entries.slice(-WINDOW_ENTRIES);
  const counts = new Map<string, { file: string; count: number }>();
  for (const e of window) {
    const key = `${e.f}\u0000${e.agent ?? ''}`;
    const cur = counts.get(key);
    if (cur) cur.count += 1;
    else counts.set(key, { file: e.f, count: 1 });
  }
  const thrashing = new Map<string, number>();
  for (const { file, count } of counts.values()) {
    if (count >= THRASH_THRESHOLD && count > (thrashing.get(file) ?? 0)) thrashing.set(file, count);
  }
  return thrashing;
}

export function thrashDetector(input: HookInput, ctx: HookContext = NOOP_CTX): HookResult {
  const path = getEditHistoryPath(ctx.projectDir);
  const entries = readAndTrimHistory(path);

  // Session-scope the window (#2919): the history file is shared by every
  // session in this project. Counting another session's edits produced
  // false thrash warnings, so only this session's records participate.
  // Legacy records without `sid` never match and age out via MAX_ENTRIES.
  const sid = input.session_id || ctx.sessionId || '';
  const sessionEntries = entries.filter(e => (e.sid ?? '') === sid);
  if (sessionEntries.length < THRASH_THRESHOLD) return outputSilentSuccess();

  const thrashing = findThrashingFiles(sessionEntries);
  if (thrashing.size === 0) return outputSilentSuccess();

  // Warn once per new edit (#4651): the window does not move on a prompt
  // with no edit, so without this the same warning repeats every turn.
  const newestThrashEdit = sessionEntries
    .slice(-WINDOW_ENTRIES)
    .filter(e => thrashing.has(e.f))
    .reduce((max, e) => Math.max(max, e.t), 0);
  const warnedPath = getWarnedStatePath(ctx.projectDir);
  const warned = readWarnedState(warnedPath);
  if (newestThrashEdit <= (warned[sid] ?? -Infinity)) return outputSilentSuccess();
  try {
    // Keep only sessions still present in the bounded history.
    const live = new Set(entries.map(e => e.sid ?? ''));
    const next: WarnedState = {};
    for (const [k, v] of Object.entries(warned)) if (live.has(k)) next[k] = v;
    next[sid] = newestThrashEdit;
    writeFileSync(warnedPath, JSON.stringify(next), 'utf8');
  } catch {
    // best-effort: a failed write only means the warning may repeat
  }

  const lines = Array.from(thrashing.entries())
    .sort((a, b) => b[1] - a[1])
    .map(([file, count]) => `  - ${displayPath(file, ctx.projectDir)}: ${count} edits in the last ${WINDOW_ENTRIES} events`);

  ctx.log(HOOK_NAME, `Thrash detected on ${thrashing.size} file(s)`);

  const message =
    `You've edited the same file(s) repeatedly in the last ${WINDOW_ENTRIES} edit events:\n${lines.join('\n')}\n` +
    `This pattern often signals a test↔edit or formatter↔edit loop. Consider a different approach, read the file once more end-to-end, or ask the user for guidance.`;

  return outputNotify(message, { prefix: 'thrash-detector', event: 'UserPromptSubmit' });
}

// Testing exports
export {
  readAndTrimHistory,
  findThrashingFiles,
  THRASH_THRESHOLD,
  WINDOW_ENTRIES,
  MAX_ENTRIES,
};
